import React, { useState, useEffect } from 'react';
import axios from 'axios';
import './index.css'; // Add import './App.css'; if using it

function App() {
  // ... (all existing states unchanged)

  // Updated load with normalization for courses
  const load = async (endpoint) => {
    setLoading(true);
    try {
      const res = await axios.get(`${API}/${endpoint}`);
      let fetchedData = res.data;
      if (endpoint.startsWith('courses')) {
        fetchedData = fetchedData.map(course => ({
          ...course,
          students: course.students ? course.students.map(Number) : []
        }));
      }
      setData(fetchedData);
    } catch (err) {
      console.error(err);
      setData([]);
    } finally {
      setLoading(false);
    }
  };

  // ... (login, logout, goTo, useEffect unchanged)

  // Updated enroll (unchanged, but for completeness)
  const enroll = async (courseId) => {
    try {
      await axios.post(`${API}/courses/${courseId}/enroll`, { studentid: user.id });
      setData(prev => prev.map(c => c.id === courseId ? { ...c, students: [...(c.students || []), user.id] } : c));
      alert('Enrolled!');
    } catch (err) {
      alert('Enroll failed');
    }
  };

  // New drop function with await and error handling
  const drop = async (courseId) => {
    try {
      await axios.post(`${API}/courses/${courseId}/drop`, { studentid: user.id });
      setData(prev => prev.map(c => c.id === courseId ? { ...c, students: c.students.filter(s => s !== user.id) } : c));
      alert('Dropped!');
    } catch (err) {
      alert('Drop failed');
    }
  };

  // ... (startAdd, startEdit, saveItem, deleteItem unchanged)

  // In the return JSX, update the button onClick for courses page (student role)
  // Find the table body, replace the existing button logic with:
  {page === 'courses' && user.role === 'student' && (
    <td>
      <button onClick={() => {
        if (item.students.includes(user.id)) {
          drop(item.id);
        } else {
          enroll(item.id);
        }
      }} className="btn">
        {item.students.includes(user.id) ? 'Drop' : 'Enroll'}
      </button>
    </td>
  )}

  // ... (rest of JSX unchanged, including instructor buttons, modals, etc.)
}

export default App;
